use anyhow::{anyhow, Context, Result};
use clap::{Parser, Subcommand};
use colored::Colorize;
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

const VERSION: &str = "ᵥ0.1.2";

// Configuration structure
#[derive(Debug, Serialize, Deserialize, Clone)]
struct Config {
    vaults: Vec<VaultInfo>,
    #[serde(default)]
    current_vault: Option<String>,
    #[serde(default)]
    current_path: Option<String>,
    #[serde(default)]
    editor: Option<String>,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
struct VaultInfo {
    name: String,
    path: PathBuf,
}

impl Config {
    fn load() -> Result<Self> {
        let config_path = Self::config_path()?;
        if config_path.exists() {
            let content = fs::read_to_string(&config_path)?;
            Ok(serde_json::from_str(&content)?)
        } else {
            Ok(Config {
                vaults: Vec::new(),
                current_vault: None,
                current_path: None,
                editor: None,
            })
        }
    }

    fn save(&self) -> Result<()> {
        let config_path = Self::config_path()?;
        if let Some(parent) = config_path.parent() {
            fs::create_dir_all(parent)?;
        }
        let content = serde_json::to_string_pretty(self)?;
        fs::write(&config_path, content)?;
        Ok(())
    }

    fn config_path() -> Result<PathBuf> {
        let config_dir = dirs::config_dir().ok_or_else(|| anyhow!("Could not find config directory"))?;
        Ok(config_dir.join("jot").join("config.json"))
    }
}

#[derive(Parser)]
#[command(name = "jt")]
#[command(version)]
#[command(about, long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    /// create a vault or list vaults
    #[command(alias = "vl")]
    Vault {
        /// name for new vault
        vault_name: Option<String>,
        /// absolute path to location of new vault
        vault_location: Option<PathBuf>,
        /// show vaults' location
        #[arg(short = 'l')]
        list: bool,
    },
    /// create a note
    #[command(alias = "nt")]
    Note {
        /// name for new note (to be created in the current folder)
        note_name: Option<String>,
    },
    /// create a folder
    #[command(alias = "fd")]
    Folder {
        /// name for new folder (to be created in the current folder)
        folder_name: Option<String>,
    },
    /// enter a vault
    #[command(alias = "en")]
    Enter {
        /// name of the vault to enter
        vault_name: String,
    },
    /// open a note (from the current folder)
    #[command(alias = "op")]
    Open {
        /// name of note to be opened
        note_name: String,
    },
    /// open current folder in file explorer
    #[command(alias = "od")]
    Opdir,
    /// change folder within current vault
    #[command(alias = "cd")]
    Chdir {
        /// path to folder to switch to (from current folder)
        folder_path: String,
    },
    /// list items in current folder
    #[command(alias = "ls")]
    List {
        /// item type (note or folder)
        #[arg(value_parser = ["note", "nt", "folder", "fd", "vault", "vl"])]
        item_type: Option<String>,
    },
    /// remove an item
    #[command(alias = "rm")]
    Remove {
        /// remove a vault (or vl) | note (or nt) | folder (or fd)
        item_type: String,
        /// name of item to be removed
        name: String,
    },
    /// rename an item
    #[command(alias = "rn")]
    Rename {
        /// rename a vault (or vl) | note (or nt) | folder (or fd)
        item_type: String,
        /// name of item to be renamed
        name: String,
        /// new name of item
        new_name: String,
    },
    /// move an item
    #[command(alias = "mv")]
    Move {
        /// move a vault (or vl) | note (or nt) | folder (or fd)
        item_type: String,
        /// name of item to be moved
        name: String,
        /// path to new location of item (current folder as root in case of note or folder)
        new_location: String,
    },
    /// move notes and folders to a different vault
    #[command(alias = "vm")]
    Vmove {
        /// move a note (or nt) | folder (or fd)
        item_type: String,
        /// name of item to be moved
        name: String,
        /// name of vault to move the item to
        vault_name: String,
    },
    /// display, set or open config
    #[command(alias = "cf")]
    Config {
        /// name of config item to display or set
        config_type: Option<String>,
        /// pass a value if config needs to be updated
        config_value: Option<String>,
    },
    /// get help for a command
    Help {
        /// command name
        command: Option<String>,
    },
}

fn print_banner() {
    let banner = r#"
[0;34m________      _____ 
______(_)_______  /_
_____  /_  __ \  __/
____  / / /_/ / /_  
___  /  \____/\__/  
/___/         [0m"#;
    println!("{}", banner);
    println!("         {}\n", VERSION);
}

fn print_help() {
    print_banner();
    println!("{}",  "usage: jt <command>".blue());
    println!();
    println!("{}:", "commands".blue());
    println!();
    println!("create items");
    println!("    {}        create a vault or list vaults", "vault, vl".blue());
    println!("    create items in current folder");
    println!("        {}         create a note ", "note, nt".blue());
    println!("        {}       create a folder", "folder, fd".blue());
    println!();
    println!("interact with items");
    println!("    {}        enter a vault", "enter, en".blue());
    println!("    {}         open a note from current folder", "open, op".blue());
    println!("    {}        open current folder in file explorer", "opdir, od".blue());
    println!("    {}        change folder within current vault", "chdir, cd".blue());
    println!("    {}         list items in current folder", "list, ls".blue());
    println!();
    println!("perform fs operations on items");
    println!("    {}         remove an item ", "remove, rm".blue());
    println!("    {}        rename an item ", "rename, rn".blue());
    println!("    {}         move an item to a new location", "move, mv".blue());
    println!("    {}        move an item to a different vault", "vmove, vm".blue());
    println!();
    println!("config");
    println!("    {}       display, set or open config", "config, cf".blue());
    println!();
    println!("get help ");
    println!("    use {} and {} flags along with a command to get corresponding help", "help".blue(), "-h and --help".blue());
}

fn normalize_item_type(item_type: &str) -> String {
    match item_type {
        "vl" => "vault".to_string(),
        "nt" => "note".to_string(),
        "fd" => "folder".to_string(),
        _ => item_type.to_string(),
    }
}

fn handle_vault(config: &mut Config, vault_name: Option<String>, vault_location: Option<PathBuf>, list: bool) -> Result<()> {
    if list || (vault_name.is_none() && vault_location.is_none()) {
        // List vaults
        if config.vaults.is_empty() {
            println!("No vaults created yet.");
        } else {
            for vault in &config.vaults {
                if list {
                    println!("{} - {}", vault.name, vault.path.display());
                } else {
                    println!("{}", vault.name);
                }
            }
        }
        return Ok(());
    }

    let vault_name = vault_name.ok_or_else(|| anyhow!("vault name required"))?;
    let vault_location = vault_location.ok_or_else(|| anyhow!("vault location required"))?;

    // Create vault
    if !vault_location.exists() {
        fs::create_dir_all(&vault_location)?;
    }

    // Check if vault already exists
    if config.vaults.iter().any(|v| v.name == vault_name) {
        return Err(anyhow!("Vault '{}' already exists", vault_name));
    }

    config.vaults.push(VaultInfo {
        name: vault_name,
        path: vault_location,
    });
    config.save()?;
    Ok(())
}

fn handle_note(config: &Config, note_name: Option<String>) -> Result<()> {
    let vault = get_current_vault(config)?;
    let mut current_path = get_current_path(config, vault)?;

    let note_name = if let Some(name) = note_name {
        name
    } else {
        // Prompt for note name
        return Err(anyhow!("Note name required"));
    };

    let note_path = current_path.join(format!("{}.md", note_name));

    if note_path.exists() {
        return Err(anyhow!("Note '{}' already exists", note_name));
    }

    fs::write(&note_path, "")?;
    println!("Created note: {}", note_name);
    Ok(())
}

fn handle_folder(config: &Config, folder_name: Option<String>) -> Result<()> {
    let vault = get_current_vault(config)?;
    let current_path = get_current_path(config, vault)?;

    let folder_name = if let Some(name) = folder_name {
        name
    } else {
        return Err(anyhow!("Folder name required"));
    };

    let folder_path = current_path.join(&folder_name);

    if folder_path.exists() {
        return Err(anyhow!("Folder '{}' already exists", folder_name));
    }

    fs::create_dir_all(&folder_path)?;
    println!("Created folder: {}", folder_name);
    Ok(())
}

fn handle_enter(config: &mut Config, vault_name: String) -> Result<()> {
    let vault = config.vaults.iter().find(|v| v.name == vault_name)
        .ok_or_else(|| anyhow!("Vault '{}' not found", vault_name))?;

    config.current_vault = Some(vault_name);
    config.current_path = Some(String::new());
    config.save()?;
    println!("Entered vault: {}", vault.name);
    Ok(())
}

fn handle_open(config: &Config, note_name: String) -> Result<()> {
    let vault = get_current_vault(config)?;
    let current_path = get_current_path(config, vault)?;

    let note_path = current_path.join(format!("{}.md", note_name));

    if !note_path.exists() {
        return Err(anyhow!("Note '{}' not found", note_name));
    }

    let editor = config.editor.clone().unwrap_or_else(|| {
        std::env::var("EDITOR").unwrap_or_else(|_| "vim".to_string())
    });

    Command::new(&editor)
        .arg(&note_path)
        .spawn()?
        .wait()?;

    Ok(())
}

fn handle_opdir(config: &Config) -> Result<()> {
    let vault = get_current_vault(config)?;
    let current_path = get_current_path(config, vault)?;

    // Try different file explorers
    let explorers = vec!["xdg-open", "nautilus", "dolphin", "caja", "thunar", "pcmanfm"];

    for explorer in explorers {
        if Command::new(explorer)
            .arg(&current_path)
            .spawn()
            .is_ok()
        {
            return Ok(());
        }
    }

    Err(anyhow!("No file explorer found"))
}

fn handle_chdir(config: &mut Config, folder_path: String) -> Result<()> {
    let vault = get_current_vault(config)?;
    let current_path = get_current_path(config, vault)?;

    let new_path = if folder_path == ".." {
        current_path.parent()
            .map(|p| p.to_path_buf())
            .ok_or_else(|| anyhow!("Already at root"))?
    } else if folder_path.starts_with('/') {
        PathBuf::from(&folder_path)
    } else {
        current_path.join(&folder_path)
    };

    if !new_path.exists() || !new_path.is_dir() {
        return Err(anyhow!("Folder not found"));
    }

    // Check if new_path is within vault
    if !new_path.starts_with(&vault.path) {
        return Err(anyhow!("Path must be within vault"));
    }

    let relative_path = new_path.strip_prefix(&vault.path)
        .unwrap_or_else(|_| &new_path);

    config.current_path = Some(relative_path.to_string_lossy().to_string());
    config.save()?;
    Ok(())
}

fn handle_list(config: &Config, item_type: Option<String>) -> Result<()> {
    let vault = get_current_vault(config)?;
    let current_path = get_current_path(config, vault)?;

    let filter = item_type.as_deref().map(normalize_item_type);

    let entries = fs::read_dir(&current_path)?;

    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        let file_name = entry.file_name();
        let file_name_str = file_name.to_string_lossy();

        if file_name_str.starts_with('.') {
            continue;
        }

        let is_note = file_name_str.ends_with(".md");
        let is_folder = path.is_dir();

        match filter.as_deref() {
            Some("note") | Some("nt") => {
                if is_note {
                    let name = file_name_str.strip_suffix(".md").unwrap_or(&file_name_str);
                    println!("{}", name);
                }
            }
            Some("folder") | Some("fd") => {
                if is_folder {
                    println!("{}", file_name_str);
                }
            }
            _ => {
                if is_note {
                    let name = file_name_str.strip_suffix(".md").unwrap_or(&file_name_str);
                    println!("{}", name);
                } else if is_folder {
                    println!("{}/", file_name_str);
                }
            }
        }
    }

    Ok(())
}

fn handle_remove(config: &mut Config, item_type: String, name: String) -> Result<()> {
    let item_type = normalize_item_type(&item_type);

    match item_type.as_str() {
        "vault" | "vl" => {
            let idx = config.vaults.iter().position(|v| v.name == name)
                .ok_or_else(|| anyhow!("Vault '{}' not found", name))?;
            config.vaults.remove(idx);
            config.save()?;
        }
        "note" | "nt" => {
            let vault = get_current_vault(config)?;
            let current_path = get_current_path(config, vault)?;
            let note_path = current_path.join(format!("{}.md", name));
            fs::remove_file(note_path)?;
        }
        "folder" | "fd" => {
            let vault = get_current_vault(config)?;
            let current_path = get_current_path(config, vault)?;
            let folder_path = current_path.join(&name);
            fs::remove_dir_all(folder_path)?;
        }
        _ => return Err(anyhow!("Unknown item type: {}", item_type)),
    }
    Ok(())
}

fn handle_rename(config: &mut Config, item_type: String, name: String, new_name: String) -> Result<()> {
    let item_type = normalize_item_type(&item_type);

    match item_type.as_str() {
        "vault" | "vl" => {
            let vault = config.vaults.iter_mut().find(|v| v.name == name)
                .ok_or_else(|| anyhow!("Vault '{}' not found", name))?;
            vault.name = new_name;
            config.save()?;
        }
        "note" | "nt" => {
            let vault = get_current_vault(config)?;
            let current_path = get_current_path(config, vault)?;
            let old_path = current_path.join(format!("{}.md", name));
            let new_path = current_path.join(format!("{}.md", new_name));
            fs::rename(old_path, new_path)?;
        }
        "folder" | "fd" => {
            let vault = get_current_vault(config)?;
            let current_path = get_current_path(config, vault)?;
            let old_path = current_path.join(&name);
            let new_path = current_path.join(&new_name);
            fs::rename(old_path, new_path)?;
        }
        _ => return Err(anyhow!("Unknown item type: {}", item_type)),
    }
    Ok(())
}

fn handle_move(config: &mut Config, item_type: String, name: String, new_location: String) -> Result<()> {
    let item_type = normalize_item_type(&item_type);

    match item_type.as_str() {
        "vault" | "vl" => {
            let vault = config.vaults.iter_mut().find(|v| v.name == name)
                .ok_or_else(|| anyhow!("Vault '{}' not found", name))?;
            vault.path = PathBuf::from(&new_location);
            config.save()?;
        }
        "note" | "nt" => {
            let vault = get_current_vault(config)?;
            let current_path = get_current_path(config, vault)?;
            let old_path = current_path.join(format!("{}.md", name));
            let new_path = current_path.join(&new_location).join(format!("{}.md", name));
            fs::create_dir_all(new_path.parent().unwrap())?;
            fs::rename(old_path, new_path)?;
        }
        "folder" | "fd" => {
            let vault = get_current_vault(config)?;
            let current_path = get_current_path(config, vault)?;
            let old_path = current_path.join(&name);
            let new_path = current_path.join(&new_location).join(&name);
            fs::create_dir_all(new_path.parent().unwrap())?;
            fs::rename(old_path, new_path)?;
        }
        _ => return Err(anyhow!("Unknown item type: {}", item_type)),
    }
    Ok(())
}

fn handle_vmove(config: &Config, item_type: String, name: String, vault_name: String) -> Result<()> {
    let item_type = normalize_item_type(&item_type);

    let source_vault = get_current_vault(config)?;
    let source_path = get_current_path(config, source_vault)?;

    let target_vault = config.vaults.iter().find(|v| v.name == vault_name)
        .ok_or_else(|| anyhow!("Target vault '{}' not found", vault_name))?;

    match item_type.as_str() {
        "note" | "nt" => {
            let old_path = source_path.join(format!("{}.md", name));
            let new_path = target_vault.path.join(format!("{}.md", name));
            fs::rename(old_path, new_path)?;
        }
        "folder" | "fd" => {
            let old_path = source_path.join(&name);
            let new_path = target_vault.path.join(&name);
            fs::rename(old_path, new_path)?;
        }
        _ => return Err(anyhow!("Invalid item type for vmove")),
    }
    Ok(())
}

fn handle_config(config: &mut Config, config_type: Option<String>, config_value: Option<String>) -> Result<()> {
    match (config_type, config_value) {
        (None, None) => {
            // Open config in editor
            let config_path = Config::config_path()?;
            let editor = config.editor.clone().unwrap_or_else(|| {
                std::env::var("EDITOR").unwrap_or_else(|_| "vim".to_string())
            });

            Command::new(&editor)
                .arg(&config_path)
                .spawn()?
                .wait()?;
        }
        (Some(config_type), None) => {
            // Display config value
            match config_type.as_str() {
                "editor" => {
                    println!("{}", config.editor.as_deref().unwrap_or("not set"));
                }
                _ => {
                    println!("Unknown config: {}", config_type);
                }
            }
        }
        (Some(config_type), Some(config_value)) => {
            // Set config value
            match config_type.as_str() {
                "editor" => {
                    config.editor = Some(config_value);
                    config.save()?;
                }
                _ => {
                    println!("Unknown config: {}", config_type);
                }
            }
        }
    }
    Ok(())
}

fn get_current_vault(config: &Config) -> Result<&VaultInfo> {
    let vault_name = config.current_vault.as_ref()
        .ok_or_else(|| anyhow!("No vault entered. Use 'jt enter <vault>' first."))?;

    config.vaults.iter().find(|v| v.name == vault_name)
        .ok_or_else(|| anyhow!("Current vault not found"))
}

fn get_current_path(config: &Config, vault: &VaultInfo) -> Result<PathBuf> {
    let relative = config.current_path.as_ref()
        .map(|p| p.as_str())
        .unwrap_or("");

    let mut path = vault.path.clone();
    if !relative.is_empty() {
        path = path.join(relative);
    }

    Ok(path)
}

fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();

    // Handle help without subcommand
    if args.len() == 1 || (args.len() == 2 && (args[1] == "help" || args[1] == "-h" || args[1] == "--help")) {
        print_help();
        if args.len() == 1 {
            std::process::exit(2);
        }
        return Ok(());
    }

    // Handle help <command>
    if args.len() > 1 && args[1] == "help" {
        if let Some(cmd) = args.get(2) {
            // We need to reconstruct args for clap to show help for that command
            let new_args = vec![args[0].clone(), cmd.clone(), "--help".to_string()];
            let cli = Cli::try_parse_from(new_args).ok();
            if cli.is_none() {
                // If parsing failed, it's probably because clap is showing help
            }
        } else {
            print_help();
        }
        return Ok(());
    }

    let cli = Cli::parse();

    let mut config = Config::load()?;

    match cli.command {
        Some(Commands::Vault { vault_name, vault_location, list }) => {
            handle_vault(&mut config, vault_name, vault_location, list)?;
        }
        Some(Commands::Note { note_name }) => {
            handle_note(&config, note_name)?;
        }
        Some(Commands::Folder { folder_name }) => {
            handle_folder(&config, folder_name)?;
        }
        Some(Commands::Enter { vault_name }) => {
            handle_enter(&mut config, vault_name)?;
        }
        Some(Commands::Open { note_name }) => {
            handle_open(&config, note_name)?;
        }
        Some(Commands::Opdir) => {
            handle_opdir(&config)?;
        }
        Some(Commands::Chdir { folder_path }) => {
            handle_chdir(&mut config, folder_path)?;
        }
        Some(Commands::List { item_type }) => {
            handle_list(&config, item_type)?;
        }
        Some(Commands::Remove { item_type, name }) => {
            handle_remove(&mut config, item_type, name)?;
        }
        Some(Commands::Rename { item_type, name, new_name }) => {
            handle_rename(&mut config, item_type, name, new_name)?;
        }
        Some(Commands::Move { item_type, name, new_location }) => {
            handle_move(&mut config, item_type, name, new_location)?;
        }
        Some(Commands::Vmove { item_type, name, vault_name }) => {
            handle_vmove(&config, item_type, name, vault_name)?;
        }
        Some(Commands::Config { config_type, config_value }) => {
            handle_config(&mut config, config_type, config_value)?;
        }
        Some(Commands::Help { command }) => {
            if let Some(cmd) = command {
                let new_args = vec![args[0].clone(), cmd, "--help".to_string()];
                let _ = Cli::try_parse_from(new_args);
            } else {
                print_help();
            }
        }
        None => {
            print_help();
            std::process::exit(2);
        }
    }

    Ok(())
}
