fn cmd_move(config: &mut Config, args: &[String]) {
    if args.len() < 3 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>\n");
        eprintln!("USAGE:");
        eprintln!("    jt move <item type> <name> <new location>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let item_type = normalize_item_type(&args[0]);
    let name = &args[1];
    let new_location = &args[2];

    match item_type.as_str() {
        "vault" | "vl" => {
            if let Some(vault) = config.vaults.iter_mut().find(|v| v.name == *name) {
                vault.path = PathBuf::from(new_location);
                if let Err(e) = config.save() {
                    eprintln!("Error saving config: {}", e);
                    exit(1);
                }
            } else {
                eprintln!("Vault '{}' not found", name);
                exit(1);
            }
        }
        "note" | "nt" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let old_path = current_path.join(format!("{}.md", name));
            let mut new_path = current_path.join(new_location).join(format!("{}.md", name));
            if new_location.ends_with('/') {
                new_path = current_path.join(new_location).join(format!("{}.md", name));
            } else {
                new_path = current_path.join(new_location).join(format!("{}.md", name));
            }

            if let Some(parent) = new_path.parent() {
                if let Err(e) = fs::create_dir_all(parent) {
                    eprintln!("Error creating directory: {}", e);
                    exit(1);
                }
            }

            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error moving note: {}", e);
                exit(1);
            }
        }
        "folder" | "fd" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let old_path = current_path.join(name);
            let new_path = current_path.join(new_location).join(name);

            if let Some(parent) = new_path.parent() {
                if let Err(e) = fs::create_dir_all(parent) {
                    eprintln!("Error creating directory: {}", e);
                    exit(1);
                }
            }

            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error moving folder: {}", e);
                exit(1);
            }
        }
        _ => {
            eprintln!("Unknown item type: {}", item_type);
            exit(1);
        }
    }
}

fn cmd_vmove(config: &Config, args: &[String]) {
    if args.len() < 3 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>\n");
        eprintln!("USAGE:");
        eprintln!("    jt vmove <item type> <name> <vault name>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let item_type = normalize_item_type(&args[0]);
    let name = &args[1];
    let vault_name = &args[2];

    let source_vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let source_path = match get_current_path(config, &source_vault) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let target_vault = config.vaults.iter()
        .find(|v| v.name == *vault_name);

    if target_vault.is_none() {
        eprintln!("Target vault '{}' not found", vault_name);
        exit(1);
    }

    let target_vault = target_vault.unwrap();

    match item_type.as_str() {
        "note" | "nt" => {
            let old_path = source_path.join(format!("{}.md", name));
            let new_path = target_vault.path.join(format!("{}.md", name));
            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error moving note: {}", e);
                exit(1);
            }
        }
        "folder" | "fd" => {
            let old_path = source_path.join(name);
            let new_path = target_vault.path.join(name);
            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error moving folder: {}", e);
                exit(1);
            }
        }
        _ => {
            eprintln!("Invalid item type for vmove");
            exit(1);
        }
    }
}

fn cmd_config(config: &mut Config, args: &[String]) {
    match args.len() {
        0 => {
            // Open config in editor
            if let Ok(config_path) = Config::config_path() {
                let editor = config.editor.clone().unwrap_or_else(|| {
                    env::var("EDITOR").unwrap_or_else(|_| "vim".to_string())
                });

                let _ = Command::new(&editor)
                    .arg(&config_path)
                    .spawn()
                    .and_then(|mut child| child.wait());
            }
        }
        1 => {
            // Display config value
            match args[0].as_str() {
                "editor" => {
                    println!("{}", config.editor.as_deref().unwrap_or("not set"));
                }
                _ => {
                    println!("Unknown config: {}", args[0]);
                }
            }
        }
        _ => {
            // Set config value
            match args[0].as_str() {
                "editor" => {
                    config.editor = Some(args[1].clone());
                    if let Err(e) = config.save() {
                        eprintln!("Error saving config: {}", e);
                        exit(1);
                    }
                }
                _ => {
                    println!("Unknown config: {}", args[0]);
                }
            }
        }
    }
}

