fn cmd_chdir(config: &mut Config, args: &[String]) {
    if args.is_empty() {
        eprintln!("Folder path required");
        exit(1);
    }

    let vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let current_path = match get_current_path(config, &vault) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let folder_path = &args[0];

    let new_path = if folder_path == ".." {
        match current_path.parent() {
            Some(p) => p.to_path_buf(),
            None => {
                eprintln!("Already at root");
                exit(1);
            }
        }
    } else if folder_path.starts_with('/') {
        PathBuf::from(folder_path)
    } else {
        current_path.join(folder_path)
    };

    if !new_path.exists() || !new_path.is_dir() {
        eprintln!("Folder not found");
        exit(1);
    }

    // Check if new_path is within vault
    if !new_path.starts_with(&vault.path) {
        eprintln!("Path must be within vault");
        exit(1);
    }

    let relative_path = new_path.strip_prefix(&vault.path)
        .unwrap_or(&new_path)
        .to_string_lossy()
        .to_string();

    config.current_path = if relative_path.is_empty() {
        Some(String::new())
    } else {
        Some(relative_path)
    };
    if let Err(e) = config.save() {
        eprintln!("Error saving config: {}", e);
        exit(1);
    }
}

fn cmd_list(config: &Config, args: &[String]) {
    let vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let current_path = match get_current_path(config, &vault) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let filter = args.get(0).map(|t| normalize_item_type(t));

    match fs::read_dir(&current_path) {
        Ok(entries) => {
            let mut items: Vec<_> = entries.filter_map(|e| e.ok()).collect();
            items.sort_by_key(|e| e.path());

            for entry in items {
                let path = entry.path();
                let file_name = entry.file_name();
                let file_name_str = file_name.to_string_lossy();

                if file_name_str.starts_with('.') {
                    continue;
                }

                let is_note = file_name_str.ends_with(".md");
                let is_folder = path.is_dir();

                match filter.as_deref() {
                    Some("note") | Some("nt") => {
                        if is_note {
                            if let Some(name) = file_name_str.strip_suffix(".md") {
                                println!("{}", name);
                            }
                        }
                    }
                    Some("folder") | Some("fd") => {
                        if is_folder {
                            println!("{}", file_name_str);
                        }
                    }
                    _ => {
                        if is_note {
                            if let Some(name) = file_name_str.strip_suffix(".md") {
                                println!("{}", name);
                            }
                        } else if is_folder {
                            println!("{}/", file_name_str);
                        }
                    }
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading directory: {}", e);
            exit(1);
        }
    }
}

fn cmd_remove(config: &mut Config, args: &[String]) {
    if args.len() < 2 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>\n");
        eprintln!("USAGE:");
        eprintln!("    jt remove <item type> <name>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let item_type = normalize_item_type(&args[0]);
    let name = &args[1];

    match item_type.as_str() {
        "vault" | "vl" => {
            if let Some(idx) = config.vaults.iter().position(|v| v.name == *name) {
                config.vaults.remove(idx);
                if let Err(e) = config.save() {
                    eprintln!("Error saving config: {}", e);
                    exit(1);
                }
            } else {
                eprintln!("Vault '{}' not found", name);
                exit(1);
            }
        }
        "note" | "nt" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let note_path = current_path.join(format!("{}.md", name));
            if let Err(e) = fs::remove_file(&note_path) {
                eprintln!("Error removing note: {}", e);
                exit(1);
            }
        }
        "folder" | "fd" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let folder_path = current_path.join(name);
            if let Err(e) = fs::remove_dir_all(&folder_path) {
                eprintln!("Error removing folder: {}", e);
                exit(1);
            }
        }
        _ => {
            eprintln!("Unknown item type: {}", item_type);
            exit(1);
        }
    }
}

