                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let old_path = current_path.join(format!("{}.md", name));
            let mut new_path = current_path.join(new_location).join(format!("{}.md", name));
            if new_location.ends_with('/') {
                new_path = current_path.join(new_location).join(format!("{}.md", name));
            } else {
