fn main() {
    let args: Vec<String> = env::args().collect();

    // Handle help without subcommand
    if args.len() == 1 || (args.len() == 2 && (args[1] == "help" || args[1] == "-h" || args[1] == "--help")) {
        print_help();
        if args.len() == 1 {
            exit(2);
        }
        return;
    }

    // Handle help <command>
    if args.len() > 1 && args[1] == "help" {
        if let Some(cmd) = args.get(2) {
            print_cmd_help(cmd);
        } else {
            print_help();
        }
        return;
    }

    // Handle <command> --help or <command> -h
    if args.len() >= 2 && (args[1] == "--help" || args[1] == "-h") {
        print_cmd_help(&args[0].split('/').last().unwrap_or(&args[0]));
        return;
    }

    let mut config = Config::load();

    if args.len() < 2 {
        print_help();
        exit(2);
    }

    let cmd = &args[1];
    let cmd_args: Vec<String> = args[2..].to_vec();

    // Check for --help or -h in cmd_args
    if cmd_args.iter().any(|a| a == "--help" || a == "-h") {
        print_cmd_help(cmd);
        return;
    }

    match cmd {
        "vault" | "vl" => cmd_vault(&mut config, &cmd_args),
        "note" | "nt" => cmd_note(&config, &cmd_args),
        "folder" | "fd" => cmd_folder(&config, &cmd_args),
        "enter" | "en" => cmd_enter(&mut config, &cmd_args),
        "open" | "op" => cmd_open(&config, &cmd_args),
        "opdir" | "od" => cmd_opdir(&config),
        "chdir" | "cd" => cmd_chdir(&mut config, &cmd_args),
        "list" | "ls" => cmd_list(&config, &cmd_args),
        "remove" | "rm" => cmd_remove(&mut config, &cmd_args),
        "rename" | "rn" => cmd_rename(&mut config, &cmd_args),
        "move" | "mv" => cmd_move(&mut config, &cmd_args),
        "vmove" | "vm" => cmd_vmove(&config, &cmd_args),
        "config" | "cf" => cmd_config(&mut config, &cmd_args),
        _ => {
            eprintln!("Unknown command: {}", cmd);
            exit(2);
        }
    }
}
