fn cmd_open(config: &Config, args: &[String]) {
    if args.is_empty() {
        eprintln!("Note name required");
        exit(1);
    }

    let vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

