fn cmd_opdir(config: &Config) {
    let vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let current_path = match get_current_path(config, &vault) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let explorers = vec!["xdg-open", "nautilus", "dolphin", "caja", "thunar", "pcmanfm", "open"];

    for explorer in explorers {
        if let Ok(mut child) = Command::new(explorer)
            .arg(&current_path)
            .spawn() {
            let _ = child.wait();
            return;
        }
    }

    eprintln!("No file explorer found");
    exit(1);
}

fn cmd_chdir(config: &mut Config, args: &[String]) {
    if args.is_empty() {
        eprintln!("Folder path required");
        exit(1);
    }

    let vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let current_path = match get_current_path(config, &vault) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let folder_path = &args[0];

    let new_path = if folder_path == ".." {
        match current_path.parent() {
            Some(p) => p.to_path_buf(),
            None => {
                eprintln!("Already at root");
                exit(1);
            }
        }
    } else if folder_path.starts_with('/') {
        PathBuf::from(folder_path)
    } else {
        current_path.join(folder_path)
    };

    if !new_path.exists() || !new_path.is_dir() {
        eprintln!("Folder not found");
        exit(1);
    }

    // Check if new_path is within vault
    if !new_path.starts_with(&vault.path) {
        eprintln!("Path must be within vault");
        exit(1);
    }

    let relative_path = new_path.strip_prefix(&vault.path)
        .unwrap_or(&new_path)
        .to_string_lossy()
        .to_string();

    config.current_path = if relative_path.is_empty() {
        Some(String::new())
    } else {
        Some(relative_path)
    };
    if let Err(e) = config.save() {
        eprintln!("Error saving config: {}", e);
        exit(1);
    }
}

fn cmd_list(config: &Config, args: &[String]) {
    let vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let current_path = match get_current_path(config, &vault) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let filter = args.get(0).map(|t| normalize_item_type(t));

    match fs::read_dir(&current_path) {
        Ok(entries) => {
            let mut items: Vec<_> = entries.filter_map(|e| e.ok()).collect();
            items.sort_by_key(|e| e.path());

            for entry in items {
                let path = entry.path();
                let file_name = entry.file_name();
                let file_name_str = file_name.to_string_lossy();

                if file_name_str.starts_with('.') {
                    continue;
                }

                let is_note = file_name_str.ends_with(".md");
                let is_folder = path.is_dir();

                match filter.as_deref() {
                    Some("note") | Some("nt") => {
                        if is_note {
                            if let Some(name) = file_name_str.strip_suffix(".md") {
                                println!("{}", name);
                            }
                        }
                    }
                    Some("folder") | Some("fd") => {
                        if is_folder {
                            println!("{}", file_name_str);
                        }
                    }
                    _ => {
                        if is_note {
                            if let Some(name) = file_name_str.strip_suffix(".md") {
                                println!("{}", name);
                            }
                        } else if is_folder {
                            println!("{}/", file_name_str);
                        }
                    }
                }
            }
        }
        Err(e) => {
            eprintln!("Error reading directory: {}", e);
            exit(1);
        }
    }
}

fn cmd_remove(config: &mut Config, args: &[String]) {
    if args.len() < 2 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>\n");
        eprintln!("USAGE:");
        eprintln!("    jt remove <item type> <name>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let item_type = normalize_item_type(&args[0]);
    let name = &args[1];

    match item_type.as_str() {
        "vault" | "vl" => {
            if let Some(idx) = config.vaults.iter().position(|v| v.name == *name) {
                config.vaults.remove(idx);
                if let Err(e) = config.save() {
                    eprintln!("Error saving config: {}", e);
                    exit(1);
                }
            } else {
                eprintln!("Vault '{}' not found", name);
                exit(1);
            }
        }
        "note" | "nt" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let note_path = current_path.join(format!("{}.md", name));
            if let Err(e) = fs::remove_file(&note_path) {
                eprintln!("Error removing note: {}", e);
                exit(1);
            }
        }
        "folder" | "fd" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let folder_path = current_path.join(name);
            if let Err(e) = fs::remove_dir_all(&folder_path) {
                eprintln!("Error removing folder: {}", e);
                exit(1);
            }
        }
        _ => {
            eprintln!("Unknown item type: {}", item_type);
            exit(1);
        }
    }
}

fn cmd_rename(config: &mut Config, args: &[String]) {
    if args.len() < 3 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>\n");
        eprintln!("USAGE:");
        eprintln!("    jt rename <item type> <name> <new name>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let item_type = normalize_item_type(&args[0]);
    let name = &args[1];
    let new_name = &args[2];

    match item_type.as_str() {
        "vault" | "vl" => {
            if let Some(vault) = config.vaults.iter_mut().find(|v| v.name == *name) {
                vault.name = new_name.clone();
                if let Err(e) = config.save() {
                    eprintln!("Error saving config: {}", e);
                    exit(1);
                }
            } else {
                eprintln!("Vault '{}' not found", name);
                exit(1);
            }
        }
        "note" | "nt" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let old_path = current_path.join(format!("{}.md", name));
            let new_path = current_path.join(format!("{}.md", new_name));
            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error renaming note: {}", e);
                exit(1);
            }
        }
        "folder" | "fd" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let old_path = current_path.join(name);
            let new_path = current_path.join(new_name);
            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error renaming folder: {}", e);
                exit(1);
            }
        }
        _ => {
            eprintln!("Unknown item type: {}", item_type);
            exit(1);
        }
    }
}

fn cmd_move(config: &mut Config, args: &[String]) {
    if args.len() < 3 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>\n");
        eprintln!("USAGE:");
        eprintln!("    jt move <item type> <name> <new location>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let item_type = normalize_item_type(&args[0]);
    let name = &args[1];
    let new_location = &args[2];

    match item_type.as_str() {
        "vault" | "vl" => {
            if let Some(vault) = config.vaults.iter_mut().find(|v| v.name == *name) {
                vault.path = PathBuf::from(new_location);
                if let Err(e) = config.save() {
                    eprintln!("Error saving config: {}", e);
                    exit(1);
                }
            } else {
                eprintln!("Vault '{}' not found", name);
                exit(1);
            }
        }
        "note" | "nt" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let old_path = current_path.join(format!("{}.md", name));
            let mut new_path = current_path.join(new_location).join(format!("{}.md", name));
            if new_location.ends_with('/') {
                new_path = current_path.join(new_location).join(format!("{}.md", name));
            } else {
                new_path = current_path.join(new_location).join(format!("{}.md", name));
            }

            if let Some(parent) = new_path.parent() {
                if let Err(e) = fs::create_dir_all(parent) {
                    eprintln!("Error creating directory: {}", e);
                    exit(1);
                }
            }

            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error moving note: {}", e);
                exit(1);
            }
        }
        "folder" | "fd" => {
            let vault = match get_current_vault(config) {
                Ok(v) => v,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let current_path = match get_current_path(config, &vault) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            };

            let old_path = current_path.join(name);
            let new_path = current_path.join(new_location).join(name);

            if let Some(parent) = new_path.parent() {
                if let Err(e) = fs::create_dir_all(parent) {
                    eprintln!("Error creating directory: {}", e);
                    exit(1);
                }
            }

            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error moving folder: {}", e);
                exit(1);
            }
        }
        _ => {
            eprintln!("Unknown item type: {}", item_type);
            exit(1);
        }
    }
}

fn cmd_vmove(config: &Config, args: &[String]) {
    if args.len() < 3 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <item type>\n");
        eprintln!("USAGE:");
        eprintln!("    jt vmove <item type> <name> <vault name>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let item_type = normalize_item_type(&args[0]);
    let name = &args[1];
    let vault_name = &args[2];

    let source_vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let source_path = match get_current_path(config, &source_vault) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let target_vault = config.vaults.iter()
        .find(|v| v.name == *vault_name);

    if target_vault.is_none() {
        eprintln!("Target vault '{}' not found", vault_name);
        exit(1);
    }

    let target_vault = target_vault.unwrap();

    match item_type.as_str() {
        "note" | "nt" => {
            let old_path = source_path.join(format!("{}.md", name));
            let new_path = target_vault.path.join(format!("{}.md", name));
            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error moving note: {}", e);
                exit(1);
            }
        }
        "folder" | "fd" => {
            let old_path = source_path.join(name);
            let new_path = target_vault.path.join(name);
            if let Err(e) = fs::rename(&old_path, &new_path) {
                eprintln!("Error moving folder: {}", e);
                exit(1);
            }
        }
        _ => {
            eprintln!("Invalid item type for vmove");
            exit(1);
        }
    }
}

fn cmd_config(config: &mut Config, args: &[String]) {
    match args.len() {
        0 => {
            // Open config in editor
            if let Ok(config_path) = Config::config_path() {
                let editor = config.editor.clone().unwrap_or_else(|| {
                    env::var("EDITOR").unwrap_or_else(|_| "vim".to_string())
                });

                let _ = Command::new(&editor)
                    .arg(&config_path)
                    .spawn()
                    .and_then(|mut child| child.wait());
            }
        }
        1 => {
            // Display config value
            match args[0].as_str() {
                "editor" => {
                    println!("{}", config.editor.as_deref().unwrap_or("not set"));
                }
                _ => {
                    println!("Unknown config: {}", args[0]);
