            }
        }
        _ => {
            // Set config value
            match args[0].as_str() {
                "editor" => {
                    config.editor = Some(args[1].clone());
                    if let Err(e) = config.save() {
                        eprintln!("Error saving config: {}", e);
                        exit(1);
                    }
                }
                _ => {
                    println!("Unknown config: {}", args[0]);
                }
            }
        }
    }
}

