struct Config {
    vaults: Vec<VaultInfo>,
    current_vault: Option<String>,
    current_path: Option<String>,
    editor: Option<String>,
}

impl Config {
    fn load() -> Self {
        match Self::config_path() {
            Ok(path) if path.exists() => {
                match fs::read_to_string(&path) {
                    Ok(content) => Self::parse_config(&content),
                    Err(_) => Config {
                        vaults: Vec::new(),
                        current_vault: None,
                        current_path: None,
                        editor: None,
                    }
                }
            }
            _ => Config {
                vaults: Vec::new(),
                current_vault: None,
                current_path: None,
                editor: None,
            }
        }
    }

    fn parse_config(content: &str) -> Self {
        let mut vaults = Vec::new();
        let mut current_vault = None;
        let mut current_path = None;
        let mut editor = None;

        if let Ok(v) = parse_json_value(content) {
            if let JsonValue::Object(obj) = v {
                if let Some(JsonValue::Array(vault_array)) = obj.get("vaults") {
                    for item in vault_array {
                        if let JsonValue::Object(vault_obj) = item {
                            if let (Some(JsonValue::String(name)), Some(JsonValue::String(path))) = 
                                (vault_obj.get("name"), vault_obj.get("path")) {
                                vaults.push(VaultInfo {
                                    name: name.clone(),
                                    path: PathBuf::from(path),
                                });
                            }
                        }
                    }
                }
                if let Some(JsonValue::String(cv)) = obj.get("current_vault") {
                    current_vault = Some(cv.clone());
                }
                if let Some(JsonValue::String(cp)) = obj.get("current_path") {
                    if !cp.is_empty() {
                        current_path = Some(cp.clone());
                    }
                }
                if let Some(JsonValue::String(ed)) = obj.get("editor") {
                    if !ed.is_empty() {
                        editor = Some(ed.clone());
                    }
                }
            }
        }

        Config {
            vaults,
            current_vault,
            current_path,
            editor,
        }
    }

    fn save(&self) -> io::Result<()> {
        let config_path = Self::config_path().ok();
        if let Some(path) = config_path {
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent)?;
            }

            let json = self.to_json_string();
            fs::write(&path, json)?;
        }
        Ok(())
    }

    fn config_path() -> Result<PathBuf, String> {
        if let Some(config_dir) = env::var_os("XDG_CONFIG_HOME") {
            Ok(PathBuf::from(config_dir).join("jot").join("config.json"))
        } else if let Ok(home) = env::var("HOME") {
            Ok(PathBuf::from(home).join(".config").join("jot").join("config.json"))
        } else {
            Err("Could not find config directory".to_string())
        }
    }

    fn to_json_string(&self) -> String {
        let mut json = String::from("{\n");
        json.push_str("  \"vaults\": [\n");

        for (i, vault) in self.vaults.iter().enumerate() {
            json.push_str("    {\n");
            json.push_str(&format!("      \"name\": \"{}\",\n", escape_json(&vault.name)));
            json.push_str(&format!("      \"path\": \"{}\"\n", escape_json(&vault.path.to_string_lossy())));
            json.push_str("    }");
            if i < self.vaults.len() - 1 {
                json.push(',');
            }
            json.push('\n');
        }

        json.push_str("  ],\n");

        if let Some(cv) = &self.current_vault {
            json.push_str(&format!("  \"current_vault\": \"{}\",\n", escape_json(cv)));
        } else {
            json.push_str("  \"current_vault\": null,\n");
        }

        if let Some(cp) = &self.current_path {
            json.push_str(&format!("  \"current_path\": \"{}\",\n", escape_json(cp)));
        } else {
            json.push_str("  \"current_path\": \"\",\n");
        }

        if let Some(ed) = &self.editor {
            json.push_str(&format!("  \"editor\": \"{}\"\n", escape_json(ed)));
        } else {
            json.push_str("  \"editor\": \"\"\n");
        }

        json.push_str("}\n");
        json
    }
}

fn escape_json(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

#[derive(Clone, Debug)]
enum JsonValue {
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
    Null,
}

fn parse_json_value(s: &str) -> Result<JsonValue, String> {
    let mut chars = s.chars().peekable();
    skip_whitespace(&mut chars);
    parse_value(&mut chars)
}

fn skip_whitespace(chars: &mut std::iter::Peekable<std::str::Chars>) {
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else {
            break;
        }
    }
}

fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<JsonValue, String> {
    skip_whitespace(chars);

    match chars.peek() {
        Some(&'"') => parse_string(chars),
        Some(&'{') => parse_object(chars),
        Some(&'[') => parse_array(chars),
        Some(&'n') => {
            chars.next();
            chars.next();
            chars.next();
            chars.next();
            Ok(JsonValue::Null)
        }
        _ => Err("Unexpected character".to_string()),
    }
}

fn parse_string(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<JsonValue, String> {
    chars.next(); 
    let mut s = String::new();

    while let Some(c) = chars.next() {
        match c {
            '"' => return Ok(JsonValue::String(s)),
            '\\' => {
                match chars.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('n') => s.push('\n'),
                    Some('r') => s.push('\r'),
                    Some('t') => s.push('\t'),
                    Some(c) => s.push(c),
                    None => return Err("Unterminated string".to_string()),
                }
            }
            c => s.push(c),
        }
    }

    Err("Unterminated string".to_string())
}

fn parse_array(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<JsonValue, String> {
    chars.next();
    skip_whitespace(chars);

    let mut arr = Vec::new();

    if chars.peek() == Some(&']') {
        chars.next();
        return Ok(JsonValue::Array(arr));
    }

    loop {
        arr.push(parse_value(chars)?);
        skip_whitespace(chars);

        match chars.peek() {
            Some(&',') => {
                chars.next();
                skip_whitespace(chars);
            }
            Some(&']') => {
                chars.next();
                return Ok(JsonValue::Array(arr));
            }
            _ => return Err("Expected , or ]".to_string()),
        }
    }
}

fn parse_object(chars: &mut std::iter::Peekable<std::str::Chars>) -> Result<JsonValue, String> {
    chars.next();
    skip_whitespace(chars);

    let mut obj = HashMap::new();

    if chars.peek() == Some(&'}') {
        chars.next();
        return Ok(JsonValue::Object(obj));
    }

    loop {
        skip_whitespace(chars);

        let key = match parse_string(chars)? {
            JsonValue::String(s) => s,
            _ => return Err("Expected string key".to_string()),
        };

        skip_whitespace(chars);
        if chars.next() != Some(':') {
            return Err("Expected :".to_string());
        }
        skip_whitespace(chars);

        let value = parse_value(chars)?;
        obj.insert(key, value);

        skip_whitespace(chars);
        match chars.peek() {
            Some(&',') => {
                chars.next();
                skip_whitespace(chars);
            }
            Some(&'}') => {
                chars.next();
                return Ok(JsonValue::Object(obj));
            }
            _ => return Err("Expected , or }".to_string()),
        }
    }
}

