fn normalize_item_type(item_type: &str) -> String {
    match item_type {
        "vl" => "vault".to_string(),
        "nt" => "note".to_string(),
        "fd" => "folder".to_string(),
        _ => item_type.to_string(),
    }
}

fn get_current_vault(config: &Config) -> Result<VaultInfo, String> {
    let vault_name = config.current_vault.as_ref()
        .ok_or_else(|| "No vault entered. Use 'jt enter <vault>' first.".to_string())?;

    config.vaults.iter()
        .find(|v| v.name == *vault_name)
        .cloned()
        .ok_or_else(|| "Current vault not found".to_string())
}

fn get_current_path(config: &Config, vault: &VaultInfo) -> Result<PathBuf, String> {
    let relative = config.current_path.as_ref()
        .map(|p| p.as_str())
        .unwrap_or("");

    let mut path = vault.path.clone();
    if !relative.is_empty() {
        path = path.join(relative);
    }

    Ok(path)
}

fn cmd_vault(config: &mut Config, args: &[String]) {
    let list = args.iter().any(|a| a == "-l");

    if list || args.is_empty() {
        if config.vaults.is_empty() {
            println!("No vaults created yet.");
        } else {
            for vault in &config.vaults {
                if list {
                    println!("{} - {}", vault.name, vault.path.display());
                } else {
                    println!("{}", vault.name);
                }
            }
        }
        return;
    }

    if args.len() < 2 {
        eprintln!("error: The following required arguments were not provided:");
        eprintln!("    <vault location>\n");
        eprintln!("USAGE:");
        eprintln!("    jt vault");
        eprintln!("    jt vault -l");
        eprintln!("    jt vault <vault name> <vault location>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let vault_name = &args[0];
    let vault_location = PathBuf::from(&args[1]);

    if let Err(e) = fs::create_dir_all(&vault_location) {
        eprintln!("Error creating vault directory: {}", e);
        exit(1);
    }

    if config.vaults.iter().any(|v| v.name == *vault_name) {
        eprintln!("Vault '{}' already exists", vault_name);
        exit(1);
    }

    config.vaults.push(VaultInfo {
        name: vault_name.clone(),
        path: vault_location,
    });
    if let Err(e) = config.save() {
        eprintln!("Error saving config: {}", e);
        exit(1);
    }
}

fn cmd_note(config: &Config, args: &[String]) {
    let vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let current_path = match get_current_path(config, &vault) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    if args.is_empty() {
        eprintln!("Note name required");
        exit(1);
    }

    let note_name = &args[0];
    let note_path = current_path.join(format!("{}.md", note_name));

    if note_path.exists() {
        eprintln!("Note '{}' already exists", note_name);
        exit(1);
    }

    if let Err(e) = fs::write(&note_path, "") {
        eprintln!("Error creating note: {}", e);
        exit(1);
    }
    println!("Created note: {}", note_name);
}

fn cmd_folder(config: &Config, args: &[String]) {
    let vault = match get_current_vault(config) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };

    let current_path = match get_current_path(config, &vault) {
        Ok(p) => p,
