        eprintln!("USAGE:");
        eprintln!("    jt vmove <item type> <name> <vault name>\n");
        eprintln!("For more information try --help");
        exit(2);
    }

    let item_type = normalize_item_type(&args[0]);
    let name = &args[1];
    let vault_name = &args[2];

    let source_vault = match get_current_vault(config) {
        Ok(v) => v,
